insert into "ai_chat" select * from jsonb_populate_record(null::"ai_chat", '{"at": "2026-11-18T14:31:16.008459+09:00", "id": 2, "role": "ai", "text": "''Station (미표기)'' 객체의 이름을 ''Main Station 1-2''로 변경하고, 해당 구역의 이름도 ''Main Station 1-2''로 변경하도록 제안했습니다. 3D 미리보기를 확인하신 후 ''적용'' 버튼을 눌러주세요.", "error": null, "tools": "장면 확인 중…\nStation (미표기) 이름 변경 제안\n구역 이름 변경 제안", "username": "admin", "drawing_id": 1}');
