insert into "ai_chat" select * from jsonb_populate_record(null::"ai_chat", '{"at": "2026-11-18T15:40:41.203515+09:00", "id": 14, "role": "ai", "text": "구역 이름과 도면 글자를 다시 원래의 ''Hub 조립장''으로 되돌리는 제안을 등록했습니다.\n\n미리보기를 확인하신 후 ''적용'' 버튼을 눌러 저장해 주세요.", "error": null, "tools": "구역 이름 변경 제안\n도면 글자 변경 제안", "username": "admin", "drawing_id": 1}');
insert into "ai_chat" select * from jsonb_populate_record(null::"ai_chat", '{"at": "2026-11-18T16:22:57.756939+09:00", "id": 15, "role": "user", "text": "위에 허브 조립 지그 4개가 너무 가깝게 붙어있는데 내가 빨간색으로 그은 영역에 4개가 고르게 배치되도록 했으면해. 그리고 그 가운데에 Hub 서브조립장 이라고 텍스트가 추가 됐으면 좋겠어.\n[이미지 1장]", "error": null, "tools": null, "username": "admin", "drawing_id": 1}');
