insert into "ai_chat" select * from jsonb_populate_record(null::"ai_chat", '{"at": "2026-11-18T16:24:10.631603+09:00", "id": 18, "role": "ai", "text": "허브 조립 지그 4개(허브 조립 지그 1~4)의 위치를 지정하신 빨간색 영역 전체에 걸쳐 간격이 더 넓고 고르게 배치되도록 이동 제안을 등록했습니다. 또한 그 가운데 위치에 ''Hub 서브조립장'' 텍스트를 추가하는 제안도 함께 생성했습니다.\n\n3D 미리보기를 확인하신 후 ''적용'' 버튼을 눌러 변경 사항을 저장해 주세요.", "error": null, "tools": "허브 조립 지그 1 이동 제안\n허브 조립 지그 2 이동 제안\n허브 조립 지그 3 이동 제안\n허브 조립 지그 4 제안 취소\n허브 조립 지그 4 이동 제안\n확인 필요: ''Hub 서브조립장'' 이름의 객체가 없습니다\n도면 글자 추가 제안", "username": "admin", "drawing_id": 1}');
