insert into "ai_chat" select * from jsonb_populate_record(null::"ai_chat", '{"at": "2026-11-18T16:25:38.519393+09:00", "id": 20, "role": "ai", "text": "보내주신 이미지 배치를 참고하여 허브 조립 지그 2, 3, 4번의 위치를 오른쪽으로 더 넓게 간격을 두어 배치하도록 이동 제안을 등록했습니다. 또한 지그 2번과 3번 사이 아래쪽에 ''Hub sub 조립장'' 텍스트를 추가하는 제안도 함께 생성했습니다.\n\n3D 미리보기를 통해 확인하신 후 ''적용'' 버튼을 눌러 저장해 주세요.", "error": null, "tools": "허브 조립 지그 1 제안 취소\n허브 조립 지그 1 제안 취소\n허브 조립 지그 2 이동 제안\n허브 조립 지그 3 이동 제안\n허브 조립 지그 4 이동 제안\n도면 글자 추가 제안", "username": "admin", "drawing_id": 1}');
